  TestValidator.equals(
    "channel description matches input",
    channel.description,
    channelData.description,
  );
  TestValidator.equals(
    "channel status matches input",
    channel.status,
    channelData.status,
  );

  // Step 4: Verify system-generated fields are properly set
  TestValidator.predicate(
