    TestValidator.equals(
      "page 2 total records consistency",
      result4.pagination.records,
      result3.pagination.records,
    );
    TestValidator.equals(
      "page 2 total pages consistency",
      result4.pagination.pages,
      result3.pagination.pages,
    );
