  // Step 4: Test different limit values within valid range
  const limitValues = [5, 20, 50] as const;
  for (const limit of limitValues) {
    const limitResults =
      await api.functional.discussionBoard.member.posts.index(connection, {
        body: {
          page: 1,
          limit: limit,
