import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardSection } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardSection";

/**
 * Test that a member can successfully delete their own discussion board post.
 *
 * This test validates the complete deletion workflow including authentication,
 * post creation, and permanent removal. The test verifies that the deletion
 * operation returns the deleted post information and that subsequent attempts
 * to access the deleted post fail appropriately.
 */
export async function test_api_post_deletion_by_member(
  connection: api.IConnection,
) {
  // Step 1: Create moderator account for administrative setup
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorPassword = "moderator123";

  const moderator = await api.functional.auth.moderator.join(connection, {
    body: {
      email: moderatorEmail,
      username: RandomGenerator.alphabets(10),
      password: moderatorPassword,
      display_name: RandomGenerator.name(),
      bio: RandomGenerator.paragraph({ sentences: 3 }),
      moderation_level: "admin",
      ip: "127.0.0.1",
      href: "https://discussion-board.example.com/register",
      referrer: "https://discussion-board.example.com",
    } satisfies IDiscussionBoardModerator.ICreate,
  });
  typia.assert(moderator);

  // Step 2: Create discussion board channel
  const channel =
    await api.functional.discussionBoard.moderator.channels.create(connection, {
      body: {
        name: RandomGenerator.paragraph({ sentences: 2 }),
        description: RandomGenerator.content({ paragraphs: 1 }),
        status: "active",
      } satisfies IDiscussionBoardChannel.ICreate,
    });
  typia.assert(channel);

  // Step 3: Create section within the channel
  const section =
    await api.functional.discussionBoard.moderator.channels.sections.create(
      connection,
      {
        channelName: channel.name,
        body: {
          name: RandomGenerator.paragraph({ sentences: 2 }),
          description: RandomGenerator.content({ paragraphs: 1 }),
          channel: {
            id: channel.id,
            name: channel.name,
            description: channel.description,
            status: channel.status,
            created_at: channel.created_at,
          } satisfies IDiscussionBoardChannel.ISummary,
        } satisfies IDiscussionBoardSection.ICreate,
      },
    );
  typia.assert(section);

  // Step 4: Switch to member account
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = "member123";

  const member = await api.functional.auth.member.join(connection, {
    body: {
      email: memberEmail,
      username: RandomGenerator.alphabets(10),
      password: memberPassword,
      display_name: RandomGenerator.name(),
      bio: RandomGenerator.paragraph({ sentences: 3 }),
      ip: "127.0.0.1",
      href: "https://discussion-board.example.com/register",
      referrer: "https://discussion-board.example.com",
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(member);

  // Step 5: Create discussion board post
  const postTitle = RandomGenerator.paragraph({
    sentences: 3,
    wordMin: 5,
    wordMax: 10,
  });
  const postContent = RandomGenerator.content({
    paragraphs: 2,
    sentenceMin: 5,
    sentenceMax: 10,
  });

  const post = await api.functional.discussionBoard.member.posts.create(
    connection,
    {
      body: {
        title: postTitle,
        content: postContent,
        discussion_board_channel_id: channel.id,
        discussion_board_section_id: section.id,
      } satisfies IDiscussionBoardPost.ICreate,
    },
  );
  typia.assert(post);

  // Step 6: Delete the post
  const deletedPost = await api.functional.discussionBoard.member.posts.erase(
    connection,
    {
      postId: post.id,
    },
  );
  typia.assert(deletedPost);

  // Validate that the deleted post matches the original post
  TestValidator.equals(
    "deleted post ID matches original",
    deletedPost.id,
    post.id,
  );
  TestValidator.equals(
    "deleted post title matches original",
    deletedPost.title,
    post.title,
  );
  TestValidator.equals(
    "deleted post content matches original",
    deletedPost.content,
    post.content,
  );

  // Step 7: Verify post is permanently deleted by attempting to delete again
  await TestValidator.error("cannot delete already deleted post", async () => {
    await api.functional.discussionBoard.member.posts.erase(connection, {
      postId: post.id,
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardContentReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardContentReport";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";

export async function test_api_content_report_creation_by_member(
  connection: api.IConnection,
) {
  // Step 1: Create member account for authentication
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const member = await api.functional.auth.member.join(connection, {
    body: {
      email: memberEmail,
      username: RandomGenerator.alphabets(8),
      password: "password123",
      display_name: RandomGenerator.name(),
      bio: RandomGenerator.paragraph({ sentences: 3 }),
      ip: "127.0.0.1",
      href: "https://example.com",
      referrer: "https://example.com/signup",
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(member);

  // Step 2: Test content report creation with different report reasons
  const reportReasons = [
    "spam",
    "harassment",
    "inappropriate",
    "misinformation",
    "copyright",
    "other",
  ] as const;
  const priorityLevels = ["low", "normal", "high", "critical"] as const;

  for (const reportReason of reportReasons) {
    for (const priority of priorityLevels) {
      const reportData = {
        report_reason: reportReason,
        report_details: RandomGenerator.paragraph({ sentences: 2 }),
        priority: priority,
      } satisfies IDiscussionBoardContentReport.ICreate;

      const createdReport =
        await api.functional.discussionBoard.member.contentReports.create(
          connection,
          { body: reportData },
        );
      typia.assert(createdReport);

      // Step 3: Validate system-assigned status
      TestValidator.equals(
        "report status should be 'pending' for newly created reports",
        createdReport.status,
        "pending",
      );

      // Step 4: Verify required fields are properly set
      TestValidator.equals(
        "report reason should match input",
        createdReport.report_reason,
        reportReason,
      );

      TestValidator.equals(
        "priority level should match input",
        createdReport.priority,
        priority,
      );

      if (reportData.report_details) {
        TestValidator.equals(
          "report details should match input when provided",
          createdReport.report_details,
          reportData.report_details,
        );
      }

      // Step 5: Validate actor information
      TestValidator.equals(
        "actor ID should match member ID",
        createdReport.actor.id,
        member.id,
      );

      TestValidator.predicate(
        "report should have valid creation timestamp",
        createdReport.created_at !== undefined &&
          createdReport.created_at !== null,
      );

      TestValidator.predicate(
        "report should have valid update timestamp",
        createdReport.updated_at !== undefined &&
          createdReport.updated_at !== null,
      );
    }
  }

  // Test edge case: report without details
  const minimalReport =
    await api.functional.discussionBoard.member.contentReports.create(
      connection,
      {
        body: {
          report_reason: "spam",
          priority: "normal",
        } satisfies IDiscussionBoardContentReport.ICreate,
      },
    );
  typia.assert(minimalReport);

  TestValidator.equals(
    "minimal report should have undefined details",
    minimalReport.report_details,
    undefined,
  );
}

