  TestValidator.predicate(
    "pagination has limit",
    basicAnalytics.pagination.limit >= 0,
  );
  TestValidator.predicate(
    "pagination has records count",
    basicAnalytics.pagination.records >= 0,
  );
  TestValidator.predicate(
    "pagination has pages count",
    basicAnalytics.pagination.pages >= 0,
  );

