  await TestValidator.error("should fail for non-existent post", async () => {
    await api.functional.discussionBoard.moderator.posts.views.index(
      connection,
      {
        postId: typia.random<string & tags.Format<"uuid">>(),
        body: {
          page: 1,
          limit: 10,
