import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardChannel";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardPostLike } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPostLike";
import type { IDiscussionBoardSection } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardSection";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionBoardPostLike } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardPostLike";

/**
 * Test pagination functionality for large like datasets
 *
 * Creates moderator account and test posts, then verifies pagination controls
 * work correctly with various page sizes and record counts. Ensures proper
 * calculation of total pages and record counts for accurate analytics
 * reporting.
 */
export async function test_api_moderator_post_likes_pagination(
  connection: api.IConnection,
) {
  // Create moderator account
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderator: IDiscussionBoardModerator.IAuthorized =
    await api.functional.auth.moderator.join(connection, {
      body: {
        email: moderatorEmail,
        username: RandomGenerator.name(1),
        password: "moderator123",
        moderation_level: "admin",
        href: "https://example.com/register",
        referrer: "https://example.com",
      } satisfies IDiscussionBoardModerator.ICreate,
    });
  typia.assert(moderator);

  // Create multiple member accounts for context
  const members = await ArrayUtil.asyncRepeat(3, async (index) => {
    const memberEmail = typia.random<string & tags.Format<"email">>();
    const member: IDiscussionBoardMember.IAuthorized =
      await api.functional.auth.member.join(connection, {
        body: {
          email: memberEmail,
          username: RandomGenerator.name(1),
          password: "member123",
          href: "https://example.com/register",
          referrer: "https://example.com",
        } satisfies IDiscussionBoardMember.ICreate,
      });
    typia.assert(member);
    return member;
  });

  // Create multiple test posts
  const posts = await ArrayUtil.asyncRepeat(2, async (index) => {
    const post: IDiscussionBoardPost =
      await api.functional.discussionBoard.member.posts.create(connection, {
        body: {
          title: RandomGenerator.paragraph({
            sentences: 5,
            wordMin: 3,
            wordMax: 8,
          }),
          content: RandomGenerator.content({
            paragraphs: 2,
            sentenceMin: 10,
            sentenceMax: 15,
          }),
          discussion_board_channel_id: typia.random<
            string & tags.Format<"uuid">
          >(),
          discussion_board_section_id: typia.random<
            string & tags.Format<"uuid">
          >(),
        } satisfies IDiscussionBoardPost.ICreate,
      });
    typia.assert(post);
    return post;
  });

  // Switch back to moderator account for pagination testing
  await api.functional.auth.moderator.login(connection, {
    body: {
      email_or_username: moderatorEmail,
      password: "moderator123",
      href: "https://example.com/login",
      referrer: "https://example.com",
    } satisfies IDiscussionBoardModerator.ILogin,
  });

  // Test pagination with different page sizes
  const testPageSizes = [5, 10, 20] as const;

  for (const pageSize of testPageSizes) {
    const paginationResult: IPageIDiscussionBoardPostLike.ISummary =
      await api.functional.discussionBoard.moderator.posts.likes.index(
        connection,
        {
          postId: posts[0].id,
          body: {
            page: 1,
            limit: pageSize,
            order_by: "created_at",
            order: "desc",
          } satisfies IDiscussionBoardPostLike.IRequest,
        },
      );
    typia.assert(paginationResult);

    // Validate pagination metadata
    TestValidator.equals(
      `page size ${pageSize} should return correct limit`,
      paginationResult.pagination.limit,
      pageSize,
    );
    TestValidator.predicate(
      `page size ${pageSize} should have valid record count`,
      paginationResult.pagination.records >= 0,
    );
    TestValidator.predicate(
      `page size ${pageSize} should have valid page count`,
      paginationResult.pagination.pages >= 0,
    );
    TestValidator.equals(
      `page size ${pageSize} should be on first page`,
      paginationResult.pagination.current,
      1,
    );

    // Validate data array size matches limit (or less if fewer records)
    TestValidator.predicate(
      `page size ${pageSize} data length should not exceed limit`,
      paginationResult.data.length <= pageSize,
    );
  }

  // Test different sorting options
  const sortingOptions = ["created_at", "member"] as const;

  for (const sortBy of sortingOptions) {
    const sortedResult: IPageIDiscussionBoardPostLike.ISummary =
      await api.functional.discussionBoard.moderator.posts.likes.index(
        connection,
        {
          postId: posts[0].id,
          body: {
            page: 1,
            limit: 10,
            order_by: sortBy,
            order: "asc",
          } satisfies IDiscussionBoardPostLike.IRequest,
        },
      );
    typia.assert(sortedResult);

    TestValidator.predicate(
      `sorting by ${sortBy} should return valid data`,
      Array.isArray(sortedResult.data),
    );
  }

  // Test date range filtering
  const dateFilteredResult: IPageIDiscussionBoardPostLike.ISummary =
    await api.functional.discussionBoard.moderator.posts.likes.index(
      connection,
      {
        postId: posts[0].id,
        body: {
          page: 1,
          limit: 10,
          date_from: new Date(
            Date.now() - 7 * 24 * 60 * 60 * 1000,
          ).toISOString(),
          date_to: new Date().toISOString(),
        } satisfies IDiscussionBoardPostLike.IRequest,
      },
    );
  typia.assert(dateFilteredResult);

  TestValidator.predicate(
    "date filtered result should be valid",
    Array.isArray(dateFilteredResult.data),
  );

  // Validate pagination calculations with maximum page size
  const largePageResult: IPageIDiscussionBoardPostLike.ISummary =
    await api.functional.discussionBoard.moderator.posts.likes.index(
      connection,
      {
        postId: posts[0].id,
        body: {
          page: 1,
          limit: 100,
        } satisfies IDiscussionBoardPostLike.IRequest,
      },
    );
  typia.assert(largePageResult);

  // Verify pagination calculations are mathematically correct
  if (
    largePageResult.pagination.records > 0 &&
    largePageResult.pagination.limit > 0
  ) {
    const expectedPages = Math.ceil(
      largePageResult.pagination.records / largePageResult.pagination.limit,
    );
    TestValidator.equals(
      "pagination pages calculation should be correct",
      largePageResult.pagination.pages,
      expectedPages,
    );
  }

  // Test edge case: very small page size
  const smallPageResult: IPageIDiscussionBoardPostLike.ISummary =
    await api.functional.discussionBoard.moderator.posts.likes.index(
      connection,
      {
        postId: posts[0].id,
        body: {
          page: 1,
          limit: 1,
        } satisfies IDiscussionBoardPostLike.IRequest,
      },
    );
  typia.assert(smallPageResult);

  TestValidator.equals(
    "smallest page size should have limit 1",
    smallPageResult.pagination.limit,
    1,
  );
  TestValidator.predicate(
    "smallest page size data length should be 0 or 1",
    smallPageResult.data.length <= 1,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardChannel";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardPostLike } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPostLike";
import type { IDiscussionBoardSection } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardSection";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionBoardPostLike } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardPostLike";

/**
 * Test comparative analytics between view and like metrics.
 *
 * Creates moderator account, creates posts with varying engagement patterns,
 * then analyzes both view and like data to identify content performance trends.
 * Validates that analytics provide insights into user engagement and content
 * appreciation patterns.
 */
export async function test_api_moderator_post_likes_comparison(
  connection: api.IConnection,
) {
  // Create moderator account for authentication context
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderator: IDiscussionBoardModerator.IAuthorized =
    await api.functional.auth.moderator.join(connection, {
      body: {
        email: moderatorEmail,
        username: RandomGenerator.alphabets(8),
        password: "password123",
        display_name: RandomGenerator.name(),
        bio: RandomGenerator.paragraph({ sentences: 3 }),
        moderation_level: "basic",
        href: "https://example.com",
        referrer: "https://example.com/referrer",
      } satisfies IDiscussionBoardModerator.ICreate,
    });
  typia.assert(moderator);

  // Create multiple member accounts for varied engagement
  const members: IDiscussionBoardMember.IAuthorized[] =
    await ArrayUtil.asyncRepeat(5, async (index) => {
      const memberEmail = typia.random<string & tags.Format<"email">>();
      const member: IDiscussionBoardMember.IAuthorized =
        await api.functional.auth.member.join(connection, {
          body: {
            email: memberEmail,
            username: RandomGenerator.alphabets(8),
            password: "password123",
            display_name: RandomGenerator.name(),
            bio: RandomGenerator.paragraph({ sentences: 2 }),
            href: "https://example.com",
            referrer: "https://example.com/referrer",
          } satisfies IDiscussionBoardMember.ICreate,
        });
      typia.assert(member);
      return member;
    });

  // Create test posts with varying content for comparative analysis
  const posts: IDiscussionBoardPost[] = [];

  // Create posts with different characteristics
  for (let i = 0; i < 3; i++) {
    // Switch to member context to create posts
    await api.functional.auth.member.login(connection, {
      body: {
        email: members[i].email,
        password: "password123",
        href: "https://example.com",
        referrer: "https://example.com/referrer",
      } satisfies IDiscussionBoardMember.ILogin,
    });

    const post = await api.functional.discussionBoard.member.posts.create(
      connection,
      {
        body: {
          title: RandomGenerator.paragraph({ sentences: 5 + i }), // Varying title length
          content: RandomGenerator.content({ paragraphs: 2 + i }), // Varying content length
          discussion_board_channel_id: typia.random<
            string & tags.Format<"uuid">
          >(),
          discussion_board_section_id: typia.random<
            string & tags.Format<"uuid">
          >(),
        } satisfies IDiscussionBoardPost.ICreate,
      },
    );
    typia.assert(post);
    posts.push(post);
  }

  // Simulate varying engagement patterns by having different members "like" different posts
  const engagementRecords: { postId: string; memberId: string }[] = [];

  // Post 0: High engagement (liked by all members)
  for (const member of members) {
    engagementRecords.push({ postId: posts[0].id, memberId: member.id });
  }

  // Post 1: Medium engagement (liked by first 3 members)
  for (let i = 0; i < 3; i++) {
    engagementRecords.push({ postId: posts[1].id, memberId: members[i].id });
  }

  // Post 2: Low engagement (liked by first member only)
  engagementRecords.push({ postId: posts[2].id, memberId: members[0].id });

  // Switch back to moderator context for analytics
  await api.functional.auth.moderator.login(connection, {
    body: {
      email_or_username: moderatorEmail,
      password: "password123",
      href: "https://example.com",
      referrer: "https://example.com/referrer",
    } satisfies IDiscussionBoardModerator.ILogin,
  });

  // Test comparative analytics on each post
  const analyticsResults: {
    post: IDiscussionBoardPost;
    analytics: IPageIDiscussionBoardPostLike.ISummary;
  }[] = [];

  for (const post of posts) {
    const analytics =
      await api.functional.discussionBoard.moderator.posts.likes.index(
        connection,
        {
          postId: post.id,
          body: {
            page: 1,
            limit: 20,
            order_by: "created_at",
            order: "desc",
          } satisfies IDiscussionBoardPostLike.IRequest,
        },
      );
    typia.assert(analytics);
    analyticsResults.push({ post, analytics });

    // Validate analytics structure
    TestValidator.equals(
      "pagination structure exists",
      typeof analytics.pagination,
      "object",
    );
    TestValidator.equals(
      "data array exists",
      Array.isArray(analytics.data),
      true,
    );
    TestValidator.predicate(
      "pagination has current page",
      analytics.pagination.current >= 0,
    );
    TestValidator.predicate(
      "pagination has limit",
      analytics.pagination.limit > 0,
    );
    TestValidator.predicate(
      "pagination has records count",
      analytics.pagination.records >= 0,
    );
    TestValidator.predicate(
      "pagination has pages count",
      analytics.pagination.pages >= 0,
    );

    // Validate each like record structure
    for (const likeRecord of analytics.data) {
      TestValidator.equals(
        "like record has id",
        typeof likeRecord.id,
        "string",
      );
      TestValidator.equals(
        "like record has member",
        typeof likeRecord.member,
        "object",
      );
      TestValidator.equals(
        "like record has post",
        typeof likeRecord.post,
        "object",
      );
      TestValidator.equals(
        "like record has created_at",
        typeof likeRecord.created_at,
        "string",
      );

      TestValidator.predicate("member has id", likeRecord.member.id.length > 0);
      TestValidator.predicate(
        "member has type",
        likeRecord.member.type.length > 0,
      );
      TestValidator.predicate(
        "member has name",
        likeRecord.member.name.length > 0,
      );

      TestValidator.predicate("post has id", likeRecord.post.id.length > 0);
      TestValidator.predicate("post has type", likeRecord.post.type.length > 0);
      TestValidator.predicate(
        "post has title",
        likeRecord.post.title.length > 0,
      );
    }
  }

  // Validate comparative analytics - posts should have different engagement levels
  // Note: Since we can't actually create likes through the API (no like creation endpoint),
  // we validate that the analytics structure is correct and can handle different scenarios
  TestValidator.equals(
    "analytics results count matches posts count",
    analyticsResults.length,
    posts.length,
  );

  // Validate that each post's analytics are properly associated
  for (const result of analyticsResults) {
    TestValidator.predicate(
      "analytics post association",
      result.analytics.data.every((like) => like.post.id === result.post.id),
    );
  }

  // Test filtering capabilities with date ranges
  const filteredAnalytics =
    await api.functional.discussionBoard.moderator.posts.likes.index(
      connection,
      {
        postId: posts[0].id,
        body: {
          page: 1,
          limit: 5,
          order_by: "member",
          order: "asc",
          date_from: new Date(Date.now() - 86400000).toISOString(), // Last 24 hours
          date_to: new Date().toISOString(),
        } satisfies IDiscussionBoardPostLike.IRequest,
      },
    );
  typia.assert(filteredAnalytics);

  TestValidator.equals(
    "filtered analytics has valid structure",
    typeof filteredAnalytics.pagination,
    "object",
  );
  TestValidator.equals(
    "filtered data is array",
    Array.isArray(filteredAnalytics.data),
    true,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardChannel";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import type { IDiscussionBoardCommentAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCommentAttachment";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardMemberSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberSession";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardSection } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardSection";

/**
 * Test complete workflow for comment attachment deletion by the original
 * author. Validates that authenticated members can successfully delete
 * attachments they uploaded to their own comments, including proper cleanup of
 * file storage resources and database records. The scenario covers the entire
 * dependency chain from channel/section creation through post creation, comment
 * creation, attachment upload, and final deletion.
 */
export async function test_api_comment_attachment_deletion_by_author(
  connection: api.IConnection,
) {
  // Step 1: Create moderator account for channel/section setup
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderator: IDiscussionBoardModerator.IAuthorized =
    await api.functional.auth.moderator.join(connection, {
      body: {
        email: moderatorEmail,
        username: RandomGenerator.alphabets(8),
        password: "moderator123",
        moderation_level: "admin",
        href: "https://example.com/register",
        referrer: "https://example.com",
      } satisfies IDiscussionBoardModerator.ICreate,
    });
  typia.assert(moderator);

  // Step 2: Create discussion board channel
  const channel: IDiscussionBoardChannel =
    await api.functional.discussionBoard.moderator.channels.create(connection, {
      body: {
        name: RandomGenerator.paragraph({ sentences: 2 }),
        description: RandomGenerator.content({ paragraphs: 1 }),
        status: "active",
      } satisfies IDiscussionBoardChannel.ICreate,
    });
  typia.assert(channel);

  // Step 3: Create section within the channel
  const section: IDiscussionBoardSection =
    await api.functional.discussionBoard.moderator.channels.sections.create(
      connection,
      {
        channelName: channel.name,
        body: {
          name: RandomGenerator.paragraph({ sentences: 2 }),
          description: RandomGenerator.content({ paragraphs: 1 }),
          channel: {
            id: channel.id,
            name: channel.name,
            description: channel.description,
            status: channel.status,
            created_at: channel.created_at,
          } satisfies IDiscussionBoardChannel.ISummary,
        } satisfies IDiscussionBoardSection.ICreate,
      },
    );
  typia.assert(section);

  // Step 4: Create member account for content creation
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const member: IDiscussionBoardMember.IAuthorized =
    await api.functional.auth.member.join(connection, {
      body: {
        email: memberEmail,
        username: RandomGenerator.alphabets(8),
        password: "member123",
        href: "https://example.com/register",
        referrer: "https://example.com",
      } satisfies IDiscussionBoardMember.ICreate,
    });
  typia.assert(member);

  // Step 5: Create discussion post
  const post: IDiscussionBoardPost =
    await api.functional.discussionBoard.member.posts.create(connection, {
      body: {
        title: RandomGenerator.paragraph({ sentences: 3 }),
        content: RandomGenerator.content({ paragraphs: 2 }),
        discussion_board_channel_id: channel.id,
        discussion_board_section_id: section.id,
      } satisfies IDiscussionBoardPost.ICreate,
    });
  typia.assert(post);

  // Step 6: Create comment on the post
  const comment: IDiscussionBoardComment =
    await api.functional.discussionBoard.member.posts.comments.create(
      connection,
      {
        postId: post.id,
        body: {
          content: RandomGenerator.content({ paragraphs: 1 }),
        } satisfies IDiscussionBoardComment.ICreate,
      },
    );
  typia.assert(comment);

  // Step 7: Upload attachment to the comment
  const attachment: IDiscussionBoardCommentAttachment =
    await api.functional.discussionBoard.member.comments.attachments.create(
      connection,
      {
        commentId: comment.id,
        body: {
          file_name: "test_document.pdf",
          file_type: "application/pdf",
          file_size: typia.random<
            number & tags.Type<"int32"> & tags.Minimum<100> & tags.Maximum<5000>
          >(),
          storage_path: "/attachments/test_document.pdf",
          description: "Test document for attachment deletion",
        } satisfies IDiscussionBoardCommentAttachment.ICreate,
      },
    );
  typia.assert(attachment);

  // Step 8: Delete the attachment (main test operation)
  await api.functional.discussionBoard.member.comments.attachments.erase(
    connection,
    {
      commentId: comment.id,
      attachmentId: attachment.id,
    },
  );

  // Step 9: Verify deletion was successful by attempting to delete again (should fail)
  await TestValidator.error(
    "deleting non-existent attachment should fail",
    async () => {
      await api.functional.discussionBoard.member.comments.attachments.erase(
        connection,
        {
          commentId: comment.id,
          attachmentId: attachment.id,
        },
      );
    },
  );

  // Step 10: Test authorization boundary - create another member and attempt to delete other's attachment
  const otherMemberEmail = typia.random<string & tags.Format<"email">>();
  const otherMember: IDiscussionBoardMember.IAuthorized =
    await api.functional.auth.member.join(connection, {
      body: {
        email: otherMemberEmail,
        username: RandomGenerator.alphabets(8),
        password: "othermember123",
        href: "https://example.com/register",
        referrer: "https://example.com",
      } satisfies IDiscussionBoardMember.ICreate,
    });
  typia.assert(otherMember);

  // Create a new attachment with the original member
  const secondAttachment: IDiscussionBoardCommentAttachment =
    await api.functional.discussionBoard.member.comments.attachments.create(
      connection,
      {
        commentId: comment.id,
        body: {
          file_name: "second_document.docx",
          file_type:
            "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
          file_size: typia.random<
            number &
              tags.Type<"int32"> &
              tags.Minimum<200> &
              tags.Maximum<10000>
          >(),
          storage_path: "/attachments/second_document.docx",
          description: "Second test document for authorization testing",
        } satisfies IDiscussionBoardCommentAttachment.ICreate,
      },
    );
  typia.assert(secondAttachment);

  // Switch to other member context
  await api.functional.auth.member.login(connection, {
    body: {
      email: otherMemberEmail,
      password: "othermember123",
      href: "https://example.com/login",
      referrer: "https://example.com",
    } satisfies IDiscussionBoardMember.ILogin,
  });

  // Attempt to delete attachment belonging to original member (should fail)
  await TestValidator.error(
    "other member cannot delete attachment they don't own",
    async () => {
      await api.functional.discussionBoard.member.comments.attachments.erase(
        connection,
        {
          commentId: comment.id,
          attachmentId: secondAttachment.id,
        },
      );
    },
  );

  // Switch back to original member and delete the second attachment
  await api.functional.auth.member.login(connection, {
    body: {
      email: memberEmail,
      password: "member123",
      href: "https://example.com/login",
      referrer: "https://example.com",
    } satisfies IDiscussionBoardMember.ILogin,
  });

  // Final deletion by the original author
  await api.functional.discussionBoard.member.comments.attachments.erase(
    connection,
    {
      commentId: comment.id,
      attachmentId: secondAttachment.id,
    },
  );

  // Final validation: All operations completed successfully
  TestValidator.predicate("complete workflow executed without errors", true);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardChannel";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import type { IDiscussionBoardCommentAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCommentAttachment";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardMemberSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberSession";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardSection } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardSection";

/**
 * Test attachment deletion when multiple attachments exist on the same comment.
 * Validates that deleting one attachment does not affect other attachments on
 * the same comment and that the system properly maintains attachment references
 * and cleanup processes. Tests proper isolation between attachment records and
 * their parent comment relationships.
 */
export async function test_api_comment_attachment_deletion_with_multiple_attachments(
  connection: api.IConnection,
) {
  // Step 1: Create authenticated member account
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const member = await api.functional.auth.member.join(connection, {
    body: {
      email: memberEmail,
      username: RandomGenerator.alphaNumeric(8),
      password: "password123",
      display_name: RandomGenerator.name(),
      bio: RandomGenerator.paragraph({ sentences: 3 }),
      href: "https://example.com",
      referrer: "https://example.com/register",
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(member);

  // Step 2: Create moderator account for channel/section creation
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderator = await api.functional.auth.moderator.join(connection, {
    body: {
      email: moderatorEmail,
      username: RandomGenerator.alphaNumeric(8),
      password: "password123",
      display_name: RandomGenerator.name(),
      bio: RandomGenerator.paragraph({ sentences: 3 }),
      moderation_level: "admin",
      href: "https://example.com",
      referrer: "https://example.com/register",
    } satisfies IDiscussionBoardModerator.ICreate,
  });
  typia.assert(moderator);

  // Step 3: Create discussion channel
  const channel =
    await api.functional.discussionBoard.moderator.channels.create(connection, {
      body: {
        name: RandomGenerator.paragraph({ sentences: 2 }),
        description: RandomGenerator.paragraph({ sentences: 5 }),
        status: "active",
      } satisfies IDiscussionBoardChannel.ICreate,
    });
  typia.assert(channel);

  // Step 4: Create section within channel
  const section =
    await api.functional.discussionBoard.moderator.channels.sections.create(
      connection,
      {
        channelName: channel.name,
        body: {
          name: RandomGenerator.paragraph({ sentences: 2 }),
          description: RandomGenerator.paragraph({ sentences: 5 }),
          channel: {
            id: channel.id,
            name: channel.name,
            description: channel.description,
            status: channel.status,
            created_at: channel.created_at,
          } satisfies IDiscussionBoardChannel.ISummary,
        } satisfies IDiscussionBoardSection.ICreate,
      },
    );
  typia.assert(section);

  // Step 5: Create discussion post
  const post = await api.functional.discussionBoard.member.posts.create(
    connection,
    {
      body: {
        title: RandomGenerator.paragraph({ sentences: 3 }),
        content: RandomGenerator.content({ paragraphs: 2 }),
        discussion_board_channel_id: channel.id,
        discussion_board_section_id: section.id,
      } satisfies IDiscussionBoardPost.ICreate,
    },
  );
  typia.assert(post);

  // Step 6: Create comment on the post
  const comment =
    await api.functional.discussionBoard.member.posts.comments.create(
      connection,
      {
        postId: post.id,
        body: {
          content: RandomGenerator.paragraph({ sentences: 5 }),
        } satisfies IDiscussionBoardComment.ICreate,
      },
    );
  typia.assert(comment);

  // Step 7: Upload multiple attachments to the same comment
  const attachment1 =
    await api.functional.discussionBoard.member.comments.attachments.create(
      connection,
      {
        commentId: comment.id,
        body: {
          file_name: "document1.pdf",
          file_type: "application/pdf",
          file_size: 1024,
          storage_path: "/attachments/doc1.pdf",
          description: "First test document",
        } satisfies IDiscussionBoardCommentAttachment.ICreate,
      },
    );
  typia.assert(attachment1);

  const attachment2 =
    await api.functional.discussionBoard.member.comments.attachments.create(
      connection,
      {
        commentId: comment.id,
        body: {
          file_name: "image1.jpg",
          file_type: "image/jpeg",
          file_size: 2048,
          storage_path: "/attachments/img1.jpg",
          description: "First test image",
        } satisfies IDiscussionBoardCommentAttachment.ICreate,
      },
    );
  typia.assert(attachment2);

  const attachment3 =
    await api.functional.discussionBoard.member.comments.attachments.create(
      connection,
      {
        commentId: comment.id,
        body: {
          file_name: "data1.txt",
          file_type: "text/plain",
          file_size: 512,
          storage_path: "/attachments/data1.txt",
          description: "First test data file",
        } satisfies IDiscussionBoardCommentAttachment.ICreate,
      },
    );
  typia.assert(attachment3);

  // Validate all attachments were created successfully with correct comment references
  TestValidator.equals(
    "attachment1 comment reference",
    attachment1.comment.id,
    comment.id,
  );
  TestValidator.equals(
    "attachment2 comment reference",
    attachment2.comment.id,
    comment.id,
  );
  TestValidator.equals(
    "attachment3 comment reference",
    attachment3.comment.id,
    comment.id,
  );

  // Store original attachment properties for later comparison
  const originalAttachment1Props = {
    file_name: attachment1.file_name,
    file_type: attachment1.file_type,
    file_size: attachment1.file_size,
    storage_path: attachment1.storage_path,
    description: attachment1.description,
  };

  const originalAttachment3Props = {
    file_name: attachment3.file_name,
    file_type: attachment3.file_type,
    file_size: attachment3.file_size,
    storage_path: attachment3.storage_path,
    description: attachment3.description,
  };

  // Step 8: Delete one attachment (attachment2)
  await api.functional.discussionBoard.member.comments.attachments.erase(
    connection,
    {
      commentId: comment.id,
      attachmentId: attachment2.id,
    },
  );

  // Step 9: Verify that the deleted attachment cannot be accessed again
  await TestValidator.error(
    "deleted attachment should not be accessible",
    async () => {
      await api.functional.discussionBoard.member.comments.attachments.erase(
        connection,
        {
          commentId: comment.id,
          attachmentId: attachment2.id,
        },
      );
    },
  );

  // Step 10: Comprehensive validation of attachment isolation

  // Verify remaining attachments are still intact and unchanged
  TestValidator.equals(
    "attachment1 file name unchanged",
    attachment1.file_name,
    originalAttachment1Props.file_name,
  );
  TestValidator.equals(
    "attachment1 file type unchanged",
    attachment1.file_type,
    originalAttachment1Props.file_type,
  );
  TestValidator.equals(
    "attachment1 file size unchanged",
    attachment1.file_size,
    originalAttachment1Props.file_size,
  );
  TestValidator.equals(
    "attachment1 storage path unchanged",
    attachment1.storage_path,
    originalAttachment1Props.storage_path,
  );
  TestValidator.equals(
    "attachment1 description unchanged",
    attachment1.description,
    originalAttachment1Props.description,
  );

  TestValidator.equals(
    "attachment3 file name unchanged",
    attachment3.file_name,
    originalAttachment3Props.file_name,
  );
  TestValidator.equals(
    "attachment3 file type unchanged",
    attachment3.file_type,
    originalAttachment3Props.file_type,
  );
  TestValidator.equals(
    "attachment3 file size unchanged",
    attachment3.file_size,
    originalAttachment3Props.file_size,
  );
  TestValidator.equals(
    "attachment3 storage path unchanged",
    attachment3.storage_path,
    originalAttachment3Props.storage_path,
  );
  TestValidator.equals(
    "attachment3 description unchanged",
    attachment3.description,
    originalAttachment3Props.description,
  );

  // Validate comment references remain intact
  TestValidator.equals(
    "attachment1 comment reference remains",
    attachment1.comment.id,
    comment.id,
  );
  TestValidator.equals(
    "attachment3 comment reference remains",
    attachment3.comment.id,
    comment.id,
  );

  // Final validation: Ensure complete isolation between attachment records
  TestValidator.predicate(
    "attachments have distinct IDs",
    attachment1.id !== attachment2.id &&
      attachment1.id !== attachment3.id &&
      attachment2.id !== attachment3.id,
  );

  TestValidator.predicate(
    "deleted attachment ID differs from remaining",
    attachment1.id !== attachment2.id && attachment3.id !== attachment2.id,
  );

  // Validate that the system properly maintains attachment isolation
  TestValidator.predicate(
    "attachment deletion maintains complete isolation",
    attachment1.id !== attachment2.id &&
      attachment3.id !== attachment2.id &&
      attachment1.file_name === "document1.pdf" &&
      attachment3.file_name === "data1.txt",
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
