import { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import { IPageIDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardPost";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { ModeratorPayload } from "../decorators/payload/ModeratorPayload";

export async function patchDiscussionBoardModeratorAnalyticsPosts(props: {
  moderator: ModeratorPayload;
  body: IDiscussionBoardPost.IRequest;
}): Promise<IPageIDiscussionBoardPost.ISummary> {
  const page = props.body.page ?? 1;
  const limit = props.body.limit ?? 100;
  const skip = (page - 1) * limit;

  // Build complex where condition
  const whereCondition: Record<string, unknown> = {
    deleted_at: null,
    status: { not: "deleted" },
  };

  // Apply filters
  if (props.body.discussion_board_channel_id) {
    whereCondition.discussion_board_channel_id =
      props.body.discussion_board_channel_id;
  }

  if (props.body.discussion_board_section_id) {
    whereCondition.discussion_board_section_id =
      props.body.discussion_board_section_id;
  }

  if (props.body.actor_type) {
    whereCondition.actor_type = props.body.actor_type;
  }

  if (props.body.status) {
    whereCondition.status = props.body.status;
  }

  if (props.body.is_pinned !== undefined) {
    whereCondition.is_pinned = props.body.is_pinned;
  }

  if (props.body.is_locked !== undefined) {
    whereCondition.is_locked = props.body.is_locked;
  }

  if (props.body.created_after || props.body.created_before) {
    const createdAtCondition: Record<string, unknown> = {};
    if (props.body.created_after) {
      createdAtCondition.gte = props.body.created_after;
    }
    if (props.body.created_before) {
      createdAtCondition.lte = props.body.created_before;
    }
    whereCondition.created_at = createdAtCondition;
  }

  // Handle search
  if (props.body.search) {
    whereCondition.OR = [
      { title: { contains: props.body.search, mode: "insensitive" } },
      { content: { contains: props.body.search, mode: "insensitive" } },
    ];
  }

  // Build orderBy
  const orderBy: Record<string, "asc" | "desc"> = {};
  const orderField = props.body.order_by ?? "created_at";
  const orderDirection = props.body.order_direction ?? "desc";
  orderBy[orderField] = orderDirection;

  // Execute main query
  const [posts, total] = await Promise.all([
    MyGlobal.prisma.discussion_board_posts.findMany({
      where: whereCondition,
      skip,
      take: limit,
      orderBy,
      select: {
        id: true,
        title: true,
        created_at: true,
      },
    }),
    MyGlobal.prisma.discussion_board_posts.count({
      where: whereCondition,
    }),
  ]);

  // Transform to summary format
  const data = posts.map((post) => ({
    id: post.id as string & tags.Format<"uuid">,
    type: "post",
    title: post.title,
  }));

  return {
    pagination: {
      current: page,
      limit: limit,
      records: total,
      pages: Math.ceil(total / limit),
    },
    data,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { IPageIDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardMember";
import { ModeratorPayload } from "../decorators/payload/ModeratorPayload";

export async function patchDiscussionBoardModeratorMembers(props: {
  moderator: ModeratorPayload;
  body: IDiscussionBoardMember.IRequest;
}): Promise<IPageIDiscussionBoardMember.ISummary> {
  const { pagination, search, filter } = props.body;

  const page = Number(pagination.current);
  const limit = Number(pagination.limit);
  const skip = (page - 1) * limit;

  // Build WHERE conditions
  const whereConditions: Record<string, unknown> = {
    deleted_at: null,
  };

  // Add search condition if provided and not just whitespace
  if (search && search.trim().length > 0) {
    whereConditions.OR = [
      { username: { contains: search, mode: "insensitive" } },
      { email: { contains: search, mode: "insensitive" } },
      { display_name: { contains: search, mode: "insensitive" } },
    ];
  }

  // Add date filter conditions if provided
  if (filter) {
    if (filter.created_after || filter.created_before) {
      whereConditions.created_at = {};

      if (filter.created_after) {
        (whereConditions.created_at as any).gte = filter.created_after;
      }

      if (filter.created_before) {
        (whereConditions.created_at as any).lte = filter.created_before;
      }
    }
  }

  // Execute concurrent queries for data and count
  const [members, totalCount] = await Promise.all([
    MyGlobal.prisma.discussion_board_members.findMany({
      where: whereConditions,
      skip,
      take: limit,
      orderBy: { created_at: "desc" },
      select: {
        id: true,
        username: true,
        email: true,
        display_name: true,
        bio: true,
        created_at: true,
        updated_at: true,
      },
    }),
    MyGlobal.prisma.discussion_board_members.count({
      where: whereConditions,
    }),
  ]);

  // Convert to API response format
  const memberSummaries: IDiscussionBoardMember.ISummary[] = members.map(
    (member) => ({
      id: member.id as string & tags.Format<"uuid">,
      type: "member",
      name: member.display_name ?? member.username,
    }),
  );

  const totalRecords = Number(totalCount);
  const totalPages = totalRecords > 0 ? Math.ceil(totalRecords / limit) : 0;

  return {
    pagination: {
      current: page,
      limit: limit,
      records: totalRecords,
      pages: totalPages,
    },
    data: memberSummaries,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IDiscussionBoardModeratorSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModeratorSession";
import { IPageIDiscussionBoardModeratorSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardModeratorSession";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { ModeratorPayload } from "../decorators/payload/ModeratorPayload";

export async function patchDiscussionBoardModeratorModeratorsUsernameSessions(props: {
  moderator: ModeratorPayload;
  username: string;
  body: IDiscussionBoardModeratorSession.IRequest;
}): Promise<IPageIDiscussionBoardModeratorSession.ISummary> {
  // Verify the target moderator exists and is active
  const targetModerator =
    await MyGlobal.prisma.discussion_board_moderators.findFirst({
      where: {
        username: props.username,
        deleted_at: null,
      },
    });

  if (!targetModerator) {
    throw new HttpException("Moderator not found", 404);
  }

  // Verify the requesting moderator has permission to access these sessions
  if (targetModerator.id !== props.moderator.id) {
    throw new HttpException("Forbidden", 403);
  }

  const page = props.body.page;
  const limit = props.body.limit;
  const skip = (page - 1) * limit;

  // Build complex where conditions
  const whereConditions: Record<string, unknown> = {
    discussion_board_moderator_id: targetModerator.id,
    deleted_at: null,
  };

  // Apply search filter
  if (props.body.search) {
    whereConditions.OR = [
      { ip: { contains: props.body.search, mode: "insensitive" } },
      { href: { contains: props.body.search, mode: "insensitive" } },
      { referrer: { contains: props.body.search, mode: "insensitive" } },
    ];
  }

  // Apply IP filter
  if (props.body.ip) {
    whereConditions.ip = props.body.ip;
  }

  // Apply date range filters
  if (props.body.created_at_start || props.body.created_at_end) {
    const createdAtCondition: Record<string, unknown> = {};
    if (props.body.created_at_start) {
      createdAtCondition.gte = props.body.created_at_start;
    }
    if (props.body.created_at_end) {
      createdAtCondition.lte = props.body.created_at_end;
    }
    whereConditions.created_at = createdAtCondition;
  }

  // Apply expiration filter
  if (props.body.expired !== undefined) {
    if (props.body.expired) {
      whereConditions.expired_at = { not: null };
    } else {
      whereConditions.expired_at = null;
    }
  }

  // Build order by
  const orderBy: Record<string, "asc" | "desc"> = {};
  const sortField = props.body.sort_by || "created_at";
  const sortOrder = props.body.order || "desc";
  orderBy[sortField] = sortOrder;

  // Execute concurrent queries
  const [data, total] = await Promise.all([
    MyGlobal.prisma.discussion_board_moderator_sessions.findMany({
      where: whereConditions,
      skip,
      take: limit,
      orderBy,
    }),
    MyGlobal.prisma.discussion_board_moderator_sessions.count({
      where: whereConditions,
    }),
  ]);

  // Transform data to match API DTO
  const transformedData = data.map((session) => ({
    id: session.id as string & tags.Format<"uuid">,
    ip: session.ip,
    href: session.href,
    referrer: session.referrer,
    created_at: toISOStringSafe(session.created_at),
    updated_at: toISOStringSafe(session.updated_at),
    expired_at: session.expired_at
      ? toISOStringSafe(session.expired_at)
      : undefined,
  }));

  return {
    pagination: {
      current: page,
      limit: limit,
      records: total,
      pages: Math.ceil(total / limit),
    },
    data: transformedData,
  };
}

