      updated_at: toISOStringSafe(guest.updated_at),
      deleted_at: guest.deleted_at
        ? toISOStringSafe(guest.deleted_at)
        : undefined,
    }),
  );

  return {
    pagination: {
      current: page,
      limit,
      records: total,
      pages: Math.ceil(total / limit),
    },
